import { Sprite, SpriteMaterial } from 'three/webgpu';

/**
 * Creates a pricing card sprite node.
 * @param {Object} config – PrismNode config
 * @param {Object} ctx – runtime context
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // -----------------------------------------------------------------------
  // 1. Texture loading (async – material is patched on resolve)
  // -----------------------------------------------------------------------
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  // -----------------------------------------------------------------------
  // 2. Build sprite material (placeholder until texture loads)
  // -----------------------------------------------------------------------
  const material = new SpriteMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: false,
    sizeAttenuation: true
  });

  // -----------------------------------------------------------------------
  // 3. Sprite sizing from atlas region aspect ratio (512 × 320)
  // -----------------------------------------------------------------------
  const atlasWidth = 512;
  const atlasHeight = 320;
  const aspect = atlasWidth / atlasHeight; // ≈1.6
  const cardWidth = 2.0;                  // desired world width
  const cardHeight = cardWidth / aspect;  // ≈1.25

  const sprite = new Sprite(material);
  sprite.scale.set(cardWidth, cardHeight, 1);

  // -----------------------------------------------------------------------
  // 4. Apply atlas UV offset/scale (whole texture is the region)
  // -----------------------------------------------------------------------
  texturePromise.then((tex) => {
    tex.wrapS = tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
    tex.repeat.set(1, 1);               // no tiling
    tex.offset.set(0, 0);               // no offset
    material.map = tex;
    material.needsUpdate = true;
  });

  // -----------------------------------------------------------------------
  // 5. Scene placement (from config)
  // -----------------------------------------------------------------------
  const pos = config.scenePosition || { x: -3.2, y: -0.3, z: 0 };
  sprite.position.set(pos.x, pos.y, pos.z || 0);
  sprite.rotation.set(0, 0, 0); // sprite ignores rotation, but set for completeness

  // -----------------------------------------------------------------------
  // 6. Event handlers (none for this card)
  // -----------------------------------------------------------------------
  sprite.userData.handlers = {};

  // -----------------------------------------------------------------------
  // 7. Cleanup – dispose material and loaded texture
  // -----------------------------------------------------------------------
  sprite.userData.cleanup = () => {
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
  };

  // -----------------------------------------------------------------------
  // 8. VisualSpec checklist: card uses provided texture, no extra text/prims
  // -----------------------------------------------------------------------

  return sprite;
}
